-- table: candidates
CREATE TABLE candidates (
	name VARCHAR(200) NOT NULL, 
	source VARCHAR(64) NOT NULL, 
	position_id VARCHAR(36), 
	experience_summary TEXT, 
	skill_summary TEXT, 
	expected_salary VARCHAR(100), 
	expected_location VARCHAR(200), 
	job_intention TEXT, 
	status VARCHAR(32) NOT NULL, 
	notes TEXT, 
	archived BOOLEAN NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, owner_id VARCHAR(36) DEFAULT '00000000-0000-0000-0000-000000000001' NOT NULL, tenant_id VARCHAR(36) DEFAULT '00000000-0000-0000-0000-000000000000' NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(position_id) REFERENCES positions (id) ON DELETE SET NULL
);

-- table: conversations
CREATE TABLE conversations (
