	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, owner_id VARCHAR(36) DEFAULT '00000000-0000-0000-0000-000000000001' NOT NULL, tenant_id VARCHAR(36) DEFAULT '00000000-0000-0000-0000-000000000000' NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(candidate_id) REFERENCES candidates (id) ON DELETE CASCADE, 
	FOREIGN KEY(position_id) REFERENCES positions (id) ON DELETE SET NULL, 
